actions.script:
if (invoice != null) {
    def rmode = java.math.RoundingMode.HALF_UP
    def totCgst = BigDecimal.ZERO, totSgst = BigDecimal.ZERO, totIgst = BigDecimal.ZERO
    def enriched = []
    for (it0 in invoiceItems) {
        def m = new LinkedHashMap(it0)
        def tlds = ec.entity.find("zenith.erp.tax.TaxLineDetail")
            .condition("referenceType", "InvoiceItem").condition("referenceId", invoice.invoiceId)
            .condition("referenceSeqId", it0.invoiceItemSeqId).list()
        // stored totalTaxAmount is authoritative: explicit 0 = tax-off line, ignore stale breakdowns
        def storedGst = ((it0.cgstAmount ?: 0) + (it0.sgstAmount ?: 0) + (it0.igstAmount ?: 0)) as BigDecimal
        if (it0.totalTaxAmount != null && ((it0.totalTaxAmount as BigDecimal) == 0)) {
            tlds = null
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
        }
        if (tlds) {
            // Breakdown rows replace the stored split; adding both doubles GST.
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
            for (tl in tlds) {
                def nm = (tl.taxName ?: '').toUpperCase()
                def amt = (tl.taxAmount ?: 0) as BigDecimal
                def rt = (tl.taxRate ?: 0) as BigDecimal
                if (nm.contains('CGST')) { m.cgstAmount = ((m.cgstAmount ?: 0) as BigDecimal) + amt; m.cgstRate = rt }
                else if (nm.contains('SGST') || nm.contains('UTGST')) { m.sgstAmount = ((m.sgstAmount ?: 0) as BigDecimal) + amt; m.sgstRate = rt }
                else if (nm.contains('IGST')) { m.igstAmount = ((m.igstAmount ?: 0) as BigDecimal) + amt; m.igstRate = rt }
            }
        } else if (((it0.totalTaxAmount ?: 0) as BigDecimal) > 0 && storedGst != (it0.totalTaxAmount as BigDecimal)) {
            // Preserve a complete stored split (including legacy IGST). Infer
            // the historical local split only when no complete split exists.
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
            def itax = (it0.totalTaxAmount ?: 0) as BigDecimal
            def half = (itax / 2).setScale(2, rmode)
            m.cgstAmount = half; m.sgstAmount = itax - half
            def taxable = (it0.taxableAmount ?: 0) as BigDecimal
            if (taxable > 0) { m.cgstRate = (half * 100 / taxable).setScale(2, rmode); m.sgstRate = m.cgstRate }
        }
        if (m.cgstAmount) totCgst += m.cgstAmount as BigDecimal
        if (m.sgstAmount) totSgst += m.sgstAmount as BigDecimal
        if (m.igstAmount) totIgst += m.igstAmount as BigDecimal
        enriched.add(m)
    }
    invoiceItems = enriched
    def inv = new LinkedHashMap(invoice)
    inv.totalCgst = totCgst; inv.totalSgst = totSgst; inv.totalIgst = totIgst
    def hdrTax = (invoice.totalTaxAmount != null ? invoice.totalTaxAmount : (totCgst + totSgst + totIgst)) as BigDecimal
    // keep a NULL total NULL (legacy notes render blank words/0 totals exactly as before)
    if (invoice.invoiceTotal != null || hdrTax != 0G || invoice.roundOffAmount != null)
        inv.invoiceTotal = ((invoice.invoiceTotal ?: 0) as BigDecimal) + hdrTax + ((invoice.roundOffAmount ?: 0) as BigDecimal)
    // ZE-SETTINGS-001: fill the seller + buyer GSTIN from the party's saved record (org default
    // TaxRegistration OR active IndiaGstin) so the note shows real GSTINs instead of "Unregistered".
    // Display-only; no-op if none saved (never fabricated); a genuine stored snapshot still wins.
    def _gstinOf = { pid ->
        def _out = null
        if (pid) {
            boolean _dz = ec.artifactExecution.disableAuthz()
            try {
                for (_r in ec.entity.find("zenith.erp.tax.TaxRegistration").condition("partyId", pid).orderBy("-isDefault").list())
                    { if (_r.registrationNumber) { _out = _r.registrationNumber; break } }
                if (!_out) for (_g in ec.entity.find("zenith.erp.india.IndiaGstin").condition("partyId", pid).condition("isActive", "Y").list())
                    { if (_g.gstin) { _out = _g.gstin; break } }
            } finally { if (!_dz) ec.artifactExecution.enableAuthz() }
        }
        _out
    }
    if (!inv.supplierGstin) { def _s = _gstinOf(invoice.fromPartyId); if (_s) inv.supplierGstin = _s }
    if (!inv.buyerGstin) { def _b = _gstinOf(invoice.toPartyId); if (_b) inv.buyerGstin = _b }
    invoice = inv
    // Amount in words (Indian numbering) — the FTL's old l10n "spellout" printed "spellout<amt>"
    amountInWords = null
    if (inv.invoiceTotal != null) {
        long __n = (inv.invoiceTotal as BigDecimal).setScale(0, java.math.RoundingMode.FLOOR).longValue()
        def __o = ['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen']
        def __t = ['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety']
        Closure __h = { int x ->
            StringBuilder bb = new StringBuilder(); int hh=(int)(x/100); int rr=x%100
            if (hh>0) { bb.append(__o[hh]).append(' Hundred'); if (rr>0) bb.append(' ') }
            if (rr>0) { if (rr<20) bb.append(__o[rr]) else { bb.append(__t[(int)(rr/10)]); if (rr%10>0) bb.append(' ').append(__o[rr%10]) } }
            return bb.toString()
        }
        long c=__n.intdiv(10000000); __n=__n%10000000
        long l=__n.intdiv(100000); __n=__n%100000
        long t=__n.intdiv(1000); __n=__n%1000
        long h=__n
        StringBuilder w=new StringBuilder()
        if (c>0) w.append(__h((int)c)).append(' Crore ')
        if (l>0) w.append(__h((int)l)).append(' Lakh ')
        if (t>0) w.append(__h((int)t)).append(' Thousand ')
        if (h>0) w.append(__h((int)h))
        amountInWords = (w.toString().trim() ?: 'Zero') + ' Rupees Only'
    }
}
